import{_ as e,o as s,c as r,a0 as a}from"./chunks/framework.Bmhw_dvp.js";const h=JSON.parse('{"title":"Subtitle System","description":"","frontmatter":{},"headers":[],"relativePath":"en/features/subtitles.md","filePath":"en/features/subtitles.md","lastUpdated":1787920745000}'),i={name:"en/features/subtitles.md"};function o(l,t,n,d,c,u){return s(),r("div",null,[...t[0]||(t[0]=[a('<h1 id="subtitle-system" tabindex="-1">Subtitle System <a class="header-anchor" href="#subtitle-system" aria-label="Permalink to &quot;Subtitle System&quot;">​</a></h1><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p>Subtitles complete your viewing experience. ZViewer provides a native subtitle system that <strong>no longer converts to WebVTT</strong>. Instead, it directly parses each subtitle format and renders them using HTML/CSS for higher style fidelity.</p><p>Both <strong>external subtitles</strong> and <strong>embedded (muxed) subtitles</strong> are supported, and the subtitle the host selects is automatically synced to every viewer in the room.</p><h2 id="supported-subtitle-formats" tabindex="-1">Supported Subtitle Formats <a class="header-anchor" href="#supported-subtitle-formats" aria-label="Permalink to &quot;Supported Subtitle Formats&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Format</th><th>Description</th></tr></thead><tbody><tr><td>SRT</td><td>The most common text subtitle</td></tr><tr><td>ASS / SSA</td><td>Supports advanced styles (positioning, color, font), preserved when rendering</td></tr><tr><td>VTT</td><td>WebVTT subtitles</td></tr><tr><td>SMI</td><td>SAMI subtitles</td></tr><tr><td>SUB</td><td>MicroDVD subtitles</td></tr></tbody></table><h2 id="external-subtitles" tabindex="-1">External Subtitles <a class="header-anchor" href="#external-subtitles" aria-label="Permalink to &quot;External Subtitles&quot;">​</a></h2><p>External subtitles are subtitle files that exist independently (e.g. <code>movie.srt</code>, <code>movie.ass</code>). They can be loaded in the following ways.</p><h3 id="auto-detect" tabindex="-1">Auto-detect <a class="header-anchor" href="#auto-detect" aria-label="Permalink to &quot;Auto-detect&quot;">​</a></h3><p>When playing movies from WebDAV / FTP / OpenList / Server-Files sources, ZViewer <strong>automatically searches for subtitle files with the same name or prefix in the movie&#39;s directory</strong> and loads them. You can see them in the subtitle settings.</p><h3 id="directory-browse" tabindex="-1">Directory Browse <a class="header-anchor" href="#directory-browse" aria-label="Permalink to &quot;Directory Browse&quot;">​</a></h3><p>In the subtitle settings, click <strong>&quot;Browse Directory&quot;</strong> to browse the movie&#39;s directory and pick a subtitle file to load.</p><h3 id="url-file-upload" tabindex="-1">URL / File Upload <a class="header-anchor" href="#url-file-upload" aria-label="Permalink to &quot;URL / File Upload&quot;">​</a></h3><p>In the subtitle settings, paste a subtitle file link directly, or upload a local subtitle file.</p><h2 id="embedded-subtitles" tabindex="-1">Embedded Subtitles <a class="header-anchor" href="#embedded-subtitles" aria-label="Permalink to &quot;Embedded Subtitles&quot;">​</a></h2><p>Embedded (muxed) subtitles are <strong>subtitle tracks inside the video container</strong>. ZViewer can parse the video container (MKV) <strong>directly in the browser</strong> and extract text subtitle tracks — <strong>no server-side FFmpeg required</strong>.</p><p>Click the <strong>&quot;Embedded Subtitle Tracks&quot;</strong> button to list the text subtitle tracks inside the container; pick one to extract and play. Extraction runs entirely in the browser (custom MKV demux + sparse scanning), <strong>skipping audio/video payload</strong> to read only subtitle bytes, so even multi-gigabyte files list tracks quickly and produce subtitles in seconds.</p><blockquote><p>Only text subtitle tracks (SRT / ASS / SSA / WebVTT) can be extracted in the browser; bitmap subtitle tracks (PGS / VOBSUB) cannot.</p></blockquote><p>Support by video source:</p><table tabindex="0"><thead><tr><th>Video source</th><th>Embedded subtitles availability</th></tr></thead><tbody><tr><td>Server-Files</td><td>✅ Extracted directly in the browser (MKV demux)</td></tr><tr><td>WebDAV / OpenList</td><td>✅ Both relay and direct-link (browser reads source bytes directly)</td></tr><tr><td>Emby / Jellyfin</td><td>✅ Uses their own subtitle API</td></tr><tr><td>MP4 direct link / Bilibili</td><td>❌ Not supported (non-MKV container)</td></tr></tbody></table><h3 id="steps" tabindex="-1">Steps <a class="header-anchor" href="#steps" aria-label="Permalink to &quot;Steps&quot;">​</a></h3><ol><li>Open the player <strong>Settings</strong>, switch to the <strong>Subtitles</strong> tab.</li><li>Click <strong>&quot;Embedded Subtitle Tracks&quot;</strong> and wait for the text subtitle tracks inside the container to be listed.</li><li>Pick a track in the list; click it to extract and enable subtitles.</li></ol><blockquote><p>When you seek to any position during playback, extraction <strong>prioritizes the segment near the playback point</strong>, filling it in quickly so subtitles are not missing for long after seeking.</p></blockquote><h2 id="viewer-sync" tabindex="-1">Viewer Sync <a class="header-anchor" href="#viewer-sync" aria-label="Permalink to &quot;Viewer Sync&quot;">​</a></h2><p>Within a room, <strong>subtitles are controlled uniformly by the host</strong>. When the host loads or switches a subtitle track, all viewers automatically sync to the same configuration — no extra setup.</p><h2 id="faq" tabindex="-1">FAQ <a class="header-anchor" href="#faq" aria-label="Permalink to &quot;FAQ&quot;">​</a></h2><h3 id="embedded-subtitle-tracks-not-listed" tabindex="-1">Embedded subtitle tracks not listed? <a class="header-anchor" href="#embedded-subtitle-tracks-not-listed" aria-label="Permalink to &quot;Embedded subtitle tracks not listed?&quot;">​</a></h3><p>Confirm the video is an MKV container and has <strong>text</strong> subtitle tracks (SRT / ASS, etc.); bitmap tracks (PGS / VOBSUB) cannot be extracted in the browser. If using a direct link and the source server does not allow CORS Range access, extraction may fail — switch to the server relay instead.</p><h3 id="style-loss" tabindex="-1">Style loss? <a class="header-anchor" href="#style-loss" aria-label="Permalink to &quot;Style loss?&quot;">​</a></h3><p>ASS / SSA embedded subtitles keep their styles; if the source is plain text (e.g. SRT) there is no style information.</p>',30)])])}const p=e(i,[["render",o]]);export{h as __pageData,p as default};
